<?php
require_once 'config.php';
exigirLogin();

try {
    $totalTreinamentos = (int) $pdo->query('SELECT COUNT(*) FROM treinamentos')->fetchColumn();
    $areas = $pdo->query("SELECT id, nome, descricao, cor FROM areas ORDER BY CASE nome WHEN 'Sistemas' THEN 1 WHEN 'Redes' THEN 2 WHEN 'Segurança' THEN 3 WHEN 'Banco de Dados' THEN 4 WHEN 'IA' THEN 5 WHEN 'Web' THEN 6 WHEN 'Automação' THEN 7 WHEN 'Eletrônica' THEN 8 WHEN 'Gestão' THEN 9 ELSE 10 END, nome")->fetchAll();
    $stmt = $pdo->query('SELECT t.id, t.titulo, t.descricao, t.carga_horaria, t.status, a.nome AS area_nome FROM treinamentos t JOIN areas a ON a.id=t.area_id ORDER BY t.criado_em DESC LIMIT 6');
    $cursos = $stmt->fetchAll();
    $totalAulas = (int) $pdo->query('SELECT COUNT(*) FROM aulas')->fetchColumn();
} catch (Throwable $e) {
    error_log('TrainHub dashboard query failed: ' . $e->getMessage());
    $totalTreinamentos = 0; $totalAulas = 0; $areas = []; $cursos = [];
}
$progresso = [100, 75, 0];
$status = ['Concluído', 'Em andamento', 'Encerrado'];
$imagensAreas = ['Sistemas' => 'sistemas.png', 'Redes' => 'redes.png', 'Segurança' => 'seguranca.png', 'Banco de Dados' => 'banco-de-dados.png', 'IA' => 'ia.png', 'Web' => 'web.png', 'Automação' => 'automacao.png', 'Eletrônica' => 'eletronica.png', 'Gestão' => 'gestao.png'];
$horasAreas = ['Sistemas' => '33h', 'Redes' => '48h', 'Segurança' => '17h', 'Banco de Dados' => '76h', 'IA' => '12h', 'Web' => '21h', 'Automação' => '33h', 'Eletrônica' => '55h', 'Gestão' => '29h'];
?><!DOCTYPE html>
<html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TrainHub - Dashboard</title>
<style>
:root{font-family:Arial,Helvetica,sans-serif;color:#eef2fb}*{box-sizing:border-box}body{margin:0;background:#273143;min-height:100vh}.topo{height:36px;background:#303949;display:flex;align-items:center;justify-content:space-between;padding:0 8px;border-bottom:1px solid #3c4658;box-shadow:0 3px 13px #101722;position:relative}.logo{display:flex;align-items:center;width:28px;height:32px}.logo img{display:block;width:28px;height:28px;object-fit:contain}.dashboard-link{position:absolute;left:50%;top:4px;transform:translateX(-50%);padding:5px 10px;border-radius:11px;background:#202838;color:#d6dcec;text-decoration:none;font-size:13px}.dashboard-link:hover{background:#3958b2;color:#fff}.usuario{display:flex;align-items:center;margin-left:auto}.avatar{width:31px;height:31px;border-radius:50%;background:#080b12 url('assets/logo.png') center/22px no-repeat;border:1px solid #111}.conteudo{max-width:1120px;margin:0 auto;padding:33px 24px 60px}.cabecalho{display:flex;justify-content:space-between;align-items:end;margin-bottom:18px}.cabecalho h1{font-size:22px;margin:3px 0;color:#fff}.cabecalho p{color:#9da8bc;font-size:12px;margin:0}.cartao{background:#3a465d;border-radius:13px;padding:14px 18px;box-shadow:0 7px 16px rgba(12,19,31,.14)}.secao-topo{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.secao-topo h2{font-size:13px;font-weight:400;margin:0;color:#e1e6f1}.filtros{display:flex;gap:8px;align-items:center}.busca{width:150px;background:#242d3e;border:0;border-radius:12px;color:#e9edf7;padding:5px 10px 5px 28px;font-size:12px;outline:none}.busca::placeholder{color:#b8c0cf}.select{background:#242d3e;color:#e8edf7;border:0;border-radius:12px;padding:5px 8px;font-size:12px}.cursos{display:grid;grid-template-columns:repeat(3,1fr);gap:28px}.curso{min-width:0}.curso-capa{height:118px;border-radius:9px;background:linear-gradient(135deg,#192c52,#121925);position:relative;overflow:hidden;display:flex;align-items:center;justify-content:center;padding:16px;text-align:center}.curso-capa:before{content:'';position:absolute;inset:0;background:url('assets/background-TrainHub.png') center/cover;opacity:.19;mix-blend-mode:screen}.curso-capa h3{position:relative;font-size:17px;margin:0;text-shadow:0 2px 3px #000;z-index:1}.progresso-circulo{position:absolute;right:8px;bottom:7px;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#202938;border:4px solid #1747ff;font-size:11px;font-weight:bold;z-index:2}.progresso-circulo.zero{border-color:#aeb1b8}.curso-rodape{display:flex;justify-content:space-between;align-items:center;margin-top:6px;font-size:12px}.concluido{color:#4fd66a}.andamento{color:#ffd21c}.encerrado{color:#ff4848}.link-curso{color:#bfc9df;text-decoration:none;font-size:11px}.areas{margin-top:28px}.grade-areas{display:grid;grid-template-columns:repeat(3,1fr);gap:12px 30px}.area{display:grid;grid-template-columns:1fr auto;gap:8px;align-items:center;text-decoration:none}.area-capa{height:48px;border-radius:8px;background:linear-gradient(135deg,var(--cor),#182132);display:flex;align-items:center;padding:0 14px;position:relative;overflow:hidden}.area-capa img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.78}.area-capa:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(10,18,32,.25),rgba(10,18,32,.15))}.area-capa span{position:relative;z-index:1;font-size:16px;text-shadow:0 1px 3px #000}.estrela{color:#fff;font-size:22px}.tag{display:inline-block;background:#8993a5;color:#fff;border-radius:8px;padding:3px 5px;font-size:10px;margin-left:4px}.acoes{margin-top:28px;display:flex;gap:10px}.botao{background:#304fa5;color:#fff;text-decoration:none;border-radius:9px;padding:10px 15px;font-size:12px}.botao:hover{background:#4165c5}@media(max-width:760px){.topo{height:36px;padding:0 8px}.conteudo{padding:33px 14px 40px}.cabecalho{align-items:start;gap:12px;flex-direction:column}.cursos,.grade-areas{grid-template-columns:repeat(2,1fr);gap:18px 12px}.filtros{width:100%}.busca{flex:1}}@media(max-width:450px){.cursos,.grade-areas{grid-template-columns:1fr}.secao-topo{align-items:start;gap:8px;flex-direction:column}.filtros{width:100%}}
</style></head><body>
<header class="topo"><a class="logo" href="dashboard.php" aria-label="Início"><img src="assets/logo1.png" alt="TrainHub"></a><?php if (temPerfil('admin')): ?><a class="dashboard-link" href="admin-dashboard.php">Dashboard</a><?php endif; ?><div class="usuario"><a class="avatar" href="logout.php" aria-label="Sair"></a></div></header>
<main class="conteudo"><div class="cabecalho"><div><p>Bem-vindo ao TrainHub</p><h1>Continue sua jornada de aprendizagem</h1></div><div class="acoes"><a class="botao" href="treinamentos.php">+ Novo treinamento</a></div></div>
<section class="cartao"><div class="secao-topo"><h2>Meus Cursos <span class="tag"><?php echo $totalTreinamentos; ?></span></h2><div class="filtros"><input class="busca filtro" data-alvo="curso" type="search" placeholder="⌕  Pesquisar"><select class="select filtro" data-alvo="curso"><option value="">Todos⌄</option><option value="concluído">Concluído</option><option value="em andamento">Em andamento</option><option value="encerrado">Encerrado</option></select></div></div><div class="cursos" id="lista-cursos"><?php foreach ($cursos as $i => $curso): $p = $progresso[$i % count($progresso)]; $s = $status[$i % count($status)]; ?><article class="curso item-curso" data-busca="<?php echo esc(strtolower($curso['titulo'].' '.$curso['area_nome'].' '.$s)); ?>"><div class="curso-capa"><h3><?php echo esc($curso['titulo']); ?></h3><span class="progresso-circulo <?php echo $p === 0 ? 'zero' : ''; ?>"><?php echo $p; ?>%</span></div><div class="curso-rodape"><span class="<?php echo $p === 100 ? 'concluido' : ($p === 0 ? 'encerrado' : 'andamento'); ?>"><?php echo $s; ?></span><a class="link-curso" href="treinamento-detalhe.php?id=<?php echo (int) $curso['id']; ?>">Abrir →</a></div></article><?php endforeach; ?></div></section>
<section class="cartao areas"><div class="secao-topo"><h2>Áreas <span class="tag"><?php echo count($areas); ?></span></h2><div class="filtros"><input class="busca filtro" data-alvo="area" type="search" placeholder="⌕  Pesquisar"><select class="select"><option>Todos⌄</option></select></div></div><div class="grade-areas" id="lista-areas"><?php foreach ($areas as $area): ?><a class="area item-area" href="treinamentos.php" data-busca="<?php echo esc(strtolower($area['nome'].' '.$area['descricao'])); ?>" style="--cor:<?php echo esc($area['cor']); ?>"><div><div class="area-capa"><img src="assets/areas/<?php echo esc($imagensAreas[$area['nome']] ?? 'sistemas.png'); ?>" alt=""><span><?php echo esc($area['nome']); ?></span></div><span class="tag">STG</span><span class="tag"><?php echo esc($horasAreas[$area['nome']] ?? '0h'); ?></span></div><span class="estrela">☆</span></a><?php endforeach; ?></div></section>
</main><script>document.querySelectorAll('.filtro').forEach(function(campo){campo.addEventListener('input',function(){var alvo=campo.dataset.alvo;var termo=campo.value.toLowerCase();document.querySelectorAll('.item-'+alvo).forEach(function(item){item.style.display=item.dataset.busca.indexOf(termo)>-1?'':'none';});});});</script></body></html>
